WITH exploded AS (SELECT id, service, host, level, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) x AS attr_key, attr_value) SELECT host, BIT_OR(status_code) AS status_code_bit_or, SORT_ARRAY(COLLECT_SET(service)) AS service_list, COUNT(*) FILTER (WHERE level = 'DEBUG') AS debug_rows, BIT_AND(status_code) AS status_code_bit_and, SUM(CASE WHEN service = 'auth' THEN status_code ELSE 0 END) AS auth_status_code, SUM(status_code) FILTER (WHERE attr_key = 'region') AS region_total_status_code FROM exploded GROUP BY host HAVING COUNT(*) FILTER (WHERE level = 'DEBUG') > 1 ORDER BY host DESC NULLS LAST
